from g123_core import make_q, make_lesson
from fig_helpers_g123 import table_fig, bars_fig, fig_shape, fig_color_mix


def _q(b, num, d, p, ok, wrongs, e, s='', h='', fig=None):
    return make_q(f'TA1-B{b:02d}-{num:03d}', d, p, ok, wrongs, e, s, h, fig)


